						"psubusb %%mm2, %%mm0	\n\t"\

						"psubusb %%mm2, %%mm1	\n\t"\

						"movq %%mm0, %%mm5	\n\t"\

						"punpcklbw %%mm4, %%mm0 \n\t"\

