void helper_func(VirtIOBlockDataPlane *s)

{
    help_func();

    if (!s->started) {

        return;

    }

    s->started = false;

    trace_helper_func(s);



    /* Stop thread or cancel pending thread creation BH */

    if (s->start_bh) {

        qemu_bh_delete(s->start_bh);

        s->start_bh = NULL;

    } else {

        event_poll_notify(&s->event_poll);

        qemu_thread_join(&s->thread);

